namespace Quantum.Circuits {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;

    @EntryPoint()
    operation ThreeQubitCircuit() : (Result, Result, Result) {
        use (q1, q2, q3) = (Qubit(), Qubit(), Qubit());

        // Build a simple 3-qubit circuit
        // Layer 1: H on qubit 1
        H(q1);

        // Layer 2: CNOT from qubit 1 to qubit 2
        CNOT(q1, q2);

        // Layer 3: CNOT from qubit 2 to qubit 3
        CNOT(q2, q3);

        // Layer 4: H on qubits 1 and 2
        H(q1);
        H(q2);

        // Measure all
        let (r1, r2, r3) = (M(q1), M(q2), M(q3));

        return (r1, r2, r3);
    }

    // Demonstrate uncomputation
    operation UncomputeDemo() : Unit {
        use (reg, ancilla) = (Qubit(), Qubit());

        // Compute: store XOR of two bits in ancilla
        H(reg);
        CNOT(reg, ancilla);  // ancilla now has value of reg

        // Use ancilla for something...

        // Uncompute: reset ancilla to |0⟩
        CNOT(reg, ancilla);  // Applying again undoes the entanglement

        // Verify ancilla is |0⟩
        let result = M(ancilla);
        Message($"Ancilla reset to: {result} (should be Zero)");
    }
}
